#!/usr/bin/env python3
"""
venn_im_promoter_vs_atac.py
Draw a two-set Venn diagram: iM promoter peaks vs ATAC peaks.
Read file line counts dynamically, no need to edit numbers manually.
"""

import matplotlib.pyplot as plt
import subprocess

def count_lines(file):
    """Count file lines using wc -l, returns an integer"""
    result = subprocess.run(['wc', '-l', file], capture_output=True, text=True)
    return int(result.stdout.split()[0])

# ========== Read data dynamically ==========
# Note: these files are generated by 01_run_downstream.sh and were deduplicated with -u
A_total = count_lines('im_promoter.bed')           # iM promoter peak total (8046)
B_total = count_lines('GSE260781_ATAC.bed3')       # ATAC peak total (35053)
A_and_B = count_lines('im_promoter_atac.bed')      # intersection (7825)

only_A = A_total - A_and_B
only_B = B_total - A_and_B

print(f"iM promoter peak total: {A_total}")
print(f"ATAC peak total: {B_total}")
print(f"Intersection: {A_and_B}")
print(f"iM promoter only: {only_A}")
print(f"ATAC only: {only_B}")

# ========== Plot ==========
fig, ax = plt.subplots(figsize=(6, 5))

r = 1.0
cx1, cy1 = -0.5, 0.0   # iM promoter peaks
cx2, cy2 = 0.5, 0.0    # ATAC peaks

circle1 = plt.Circle((cx1, cy1), r, color='#E69F00', alpha=0.4, label='iM in Promoters')
circle2 = plt.Circle((cx2, cy2), r, color='#56B4E9', alpha=0.4, label='ATAC')
ax.add_patch(circle1)
ax.add_patch(circle2)

# Set labels
ax.text(cx1, cy1 - r - 0.15, 'iM in Promoters', ha='center', va='top', fontsize=12)
ax.text(cx2, cy2 - r - 0.15, 'ATAC', ha='center', va='top', fontsize=12)

# Region numbers (shown at appropriate positions inside the circles)
ax.text(cx1 - 0.5, cy1, f'{only_A}', ha='center', va='center', fontsize=14, fontweight='bold')
ax.text(cx2 + 0.5, cy2, f'{only_B}', ha='center', va='center', fontsize=14, fontweight='bold')
ax.text((cx1+cx2)/2, cy1, f'{A_and_B}', ha='center', va='center', fontsize=14, fontweight='bold')

ax.set_xlim(-2, 2)
ax.set_ylim(-1.5, 1.5)
ax.set_aspect('equal')
ax.axis('off')
plt.title('Overlap of iM promoter peaks and ATAC-seq peaks', fontsize=14)
plt.tight_layout()
plt.savefig("venn_im_promoter_vs_atac.pdf", dpi=300)
plt.savefig("venn_im_promoter_vs_atac.png", dpi=300)
print("Venn diagram saved as venn_im_promoter_vs_atac.pdf and .png")
